import { sql } from 'drizzle-orm';
import {
  check,
  index,
  integer,
  real,
  sqliteTable,
  text,
  uniqueIndex,
} from 'drizzle-orm/sqlite-core';

/** SQL timestamps are generated by the database, never at module-load time. */
const timestamps = {
  createdAt: text('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
  updatedAt: text('updated_at').notNull().default(sql`CURRENT_TIMESTAMP`),
};

export const buildings = sqliteTable(
  'buildings',
  {
    // DOB permit number/document number is the durable record identity, not BBL.
    id: text('id').primaryKey(),
    bbl: text('bbl'),
    borough: text('borough').notNull(),
    bin: integer('bin'),
    houseNumber: text('house_number'),
    streetName: text('street_name'),
    block: integer('block'),
    lot: integer('lot'),
    zipCode: text('zip_code'),
    jobId: text('job_id').notNull(),
    jobDocId: text('job_doc_id').notNull(),
    permitSequence: text('permit_sequence'),
    permitType: text('permit_type'),
    permitSubtype: text('permit_subtype'),
    workType: text('work_type'),
    ownerFullName: text('owner_full_name'),
    ownerBusinessName: text('owner_business_name'),
    permitteeBusinessName: text('permittee_business_name'),
    permitteePhone: text('permittee_phone'),
    jobType: text('job_type').notNull().default('DM'),
    buildingType: text('building_type'),
    residential: integer('residential', { mode: 'boolean' }).notNull().default(false),
    filingDate: text('filing_date'),
    issuanceDate: text('issuance_date'),
    expirationDate: text('expiration_date'),
    jobStartDate: text('job_start_date'),
    permitStatus: text('permit_status').notNull(),
    latitude: real('latitude'),
    longitude: real('longitude'),
    councilDistrict: integer('council_district'),
    censusTract: text('census_tract'),
    ntaName: text('nta_name'),
    // Phase 2 enrichment fields are explicit so they can be indexed and audited.
    constructionYear: integer('construction_year'),
    architectName: text('architect_name'),
    landmarkStatus: text('landmark_status'),
    metadata: text('metadata', { mode: 'json' })
      .$type<BuildingMetadata>()
      .notNull()
      .default({}),
    sourceUpdatedAt: text('source_updated_at'),
    ...timestamps,
  },
  (table) => [
    check('buildings_job_type_dm', sql`${table.jobType} = 'DM'`),
    index('buildings_job_document_idx').on(table.jobId, table.jobDocId),
    index('buildings_bbl_idx').on(table.bbl),
    index('buildings_status_issuance_idx').on(table.permitStatus, table.issuanceDate),
    index('buildings_location_idx').on(table.latitude, table.longitude),
    index('buildings_construction_year_idx').on(table.constructionYear),
  ],
);

export const submissions = sqliteTable(
  'submissions',
  {
    id: text('id').primaryKey(),
    buildingId: text('building_id')
      .notNull()
      .references(() => buildings.id, { onDelete: 'cascade' }),
    title: text('title').notNull(),
    content: text('content').notNull(),
    submitterName: text('submitter_name'),
    submitterEmail: text('submitter_email'),
    status: text('status').notNull().default('pending'),
    moderationScore: real('moderation_score'),
    moderationReasons: text('moderation_reasons', { mode: 'json' })
      .$type<string[]>()
      .notNull()
      .default([]),
    tags: text('tags', { mode: 'json' }).$type<string[]>().notNull().default([]),
    ...timestamps,
  },
  (table) => [
    check('submissions_status_valid', sql`${table.status} IN ('pending', 'approved', 'rejected', 'needs_edit')`),
    index('submissions_building_idx').on(table.buildingId),
    index('submissions_status_created_idx').on(table.status, table.createdAt),
  ],
);

export const submissionMedia = sqliteTable(
  'submission_media',
  {
    id: text('id').primaryKey(),
    submissionId: text('submission_id')
      .notNull()
      .references(() => submissions.id, { onDelete: 'cascade' }),
    url: text('url').notNull(),
    altText: text('alt_text'),
    mediaType: text('media_type').notNull().default('image'),
    sortOrder: integer('sort_order').notNull().default(0),
    createdAt: text('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
  },
  (table) => [index('submission_media_submission_idx').on(table.submissionId)],
);

/** Externally hosted building-image candidates; files are never copied into this app. */
export const buildingImages = sqliteTable(
  'building_images',
  {
    id: text('id').primaryKey(),
    buildingId: text('building_id').notNull().references(() => buildings.id, { onDelete: 'cascade' }),
    source: text('source').notNull(),
    sourceImageId: text('source_image_id').notNull(),
    sourcePageUrl: text('source_page_url').notNull(),
    imageUrl: text('image_url').notNull(),
    thumbnailUrl: text('thumbnail_url'),
    title: text('title'),
    creator: text('creator'),
    license: text('license'),
    licenseUrl: text('license_url'),
    capturedAt: text('captured_at'),
    matchMethod: text('match_method').notNull(),
    confidence: real('confidence').notNull().default(0),
    status: text('status').notNull().default('pending'),
    reviewNotes: text('review_notes'),
    ...timestamps,
  },
  (table) => [
    check('building_images_status_valid', sql`${table.status} IN ('pending', 'approved', 'rejected')`),
    uniqueIndex('building_images_source_unique').on(table.source, table.sourceImageId),
    index('building_images_building_status_idx').on(table.buildingId, table.status),
  ],
);

export const adminReviews = sqliteTable(
  'admin_reviews',
  {
    id: text('id').primaryKey(),
    submissionId: text('submission_id')
      .notNull()
      .references(() => submissions.id, { onDelete: 'cascade' }),
    reviewer: text('reviewer').notNull(),
    decision: text('decision').notNull(),
    notes: text('notes'),
    createdAt: text('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
  },
  (table) => [
    check('admin_reviews_decision_valid', sql`${table.decision} IN ('approve', 'reject', 'request_edit')`),
    index('admin_reviews_submission_idx').on(table.submissionId),
  ],
);

export const syncRuns = sqliteTable(
  'sync_runs',
  {
    id: text('id').primaryKey(),
    source: text('source').notNull(),
    status: text('status').notNull(),
    recordsRead: integer('records_read').notNull().default(0),
    recordsUpserted: integer('records_upserted').notNull().default(0),
    errorMessage: text('error_message'),
    startedAt: text('started_at').notNull().default(sql`CURRENT_TIMESTAMP`),
    completedAt: text('completed_at'),
  },
  (table) => [index('sync_runs_source_started_idx').on(table.source, table.startedAt)],
);

export type BuildingMetadata = {
  ageGt50?: boolean;
  architecturalStyles?: string[];
  historicalEvents?: string[];
  ornamentTypes?: string[];
  hiddenGemTags?: string[];
  landmarkIds?: string[];
  photoUrls?: string[];
  provenance?: Array<{ source: string; retrievedAt: string; confidence?: number }>;
};
